const lead = JSON.parse(JSON.stringify($json ?? {}));
const requiredObjects = ['source', 'contact', 'business', 'request', 'data_quality', 'identity', 'processing'];
const missing = [];
if (!lead.lead_id) missing.push('lead_id');
for (const key of requiredObjects) {
  if (!lead[key] || typeof lead[key] !== 'object' || Array.isArray(lead[key])) missing.push(key);
}
const allowedIdentity = ['unique', 'exact_duplicate', 'merged'];
if (!allowedIdentity.includes(lead.identity?.status)) missing.push('identity.status_not_eligible');
if (lead.data_quality?.validation_status !== 'valid' || lead.data_quality?.is_complete !== true) missing.push('data_quality_not_valid');
if (lead.processing?.status === 'manual_review') missing.push('processing_manual_review');
if (missing.length) throw new Error(`WF02 handoff is not eligible for automated qualification: ${missing.join(', ')}`);
lead.processing.current_workflow = 'WF03_enrichment_qualification';
lead.processing.next_workflow = null;
lead.processing.updated_at = new Date().toISOString();
lead.wf03_context = { execution_id: $execution.id, started_at: new Date().toISOString() };
return [{ json: lead }];

const workflowLead = JSON.parse(JSON.stringify($json.workflow_lead ?? {}));
const row = $json;
if (!row.id) throw new Error('Canonical lead was not found in PostgreSQL.');
const value = (db, fallback) => db !== null && db !== undefined ? db : fallback;
workflowLead.lead_id = row.id;
workflowLead.source = { ...(workflowLead.source ?? {}), type: value(row.source, workflowLead.source?.type), external_id: value(row.external_source_id, workflowLead.source?.external_id), received_at: value(row.received_at, workflowLead.source?.received_at) };
workflowLead.contact = { ...(workflowLead.contact ?? {}), name: value(row.name, workflowLead.contact?.name), phone_raw: value(row.phone_raw, workflowLead.contact?.phone_raw), phone_normalized: value(row.phone_normalized, workflowLead.contact?.phone_normalized), email_raw: value(row.email_raw, workflowLead.contact?.email_raw), email_normalized: value(row.email_normalized, workflowLead.contact?.email_normalized), consent: value(row.consent, workflowLead.contact?.consent) };
workflowLead.business = { ...(workflowLead.business ?? {}), company_name: value(row.company_name, workflowLead.business?.company_name), service_interest: value(row.service_interest, workflowLead.business?.service_interest), country: value(row.country, workflowLead.business?.country), industry: value(row.industry, workflowLead.business?.industry), company_size: value(row.company_size, workflowLead.business?.company_size), strategic_account: value(row.strategic_account, workflowLead.business?.strategic_account) };
workflowLead.request = { ...(workflowLead.request ?? {}), message: value(row.message, workflowLead.request?.message) };
workflowLead.processing = { ...(workflowLead.processing ?? {}), current_workflow: 'WF03_enrichment_qualification', updated_at: new Date().toISOString() };
return [{ json: workflowLead }];

const lead = JSON.parse(JSON.stringify($json));
const missingFields = ['company_size', 'industry', 'country'].filter((field) => lead.business?.[field] === null || lead.business?.[field] === undefined || lead.business?.[field] === '');
lead.enrichment = { required: missingFields.length > 0, requested_fields: missingFields, attempts_configured: 3, status: missingFields.length ? 'pending' : 'not_required' };
return [{ json: lead }];

const lead = JSON.parse(JSON.stringify($('Check Enrichment Need').item.json));
const raw = $json?.body ?? $json?.data ?? $json;
const errors = [];
if ($json?.error) errors.push(String($json.error.message ?? $json.error));
if (!raw || typeof raw !== 'object' || Array.isArray(raw)) errors.push('empty_or_non_object_response');
if (raw?.status !== 'success') errors.push('status_not_success');
if (raw?.industry != null && typeof raw.industry !== 'string') errors.push('industry_invalid');
if (raw?.company_size != null && (!Number.isInteger(Number(raw.company_size)) || Number(raw.company_size) < 0)) errors.push('company_size_invalid');
if (raw?.country != null && typeof raw.country !== 'string') errors.push('country_invalid');
if (raw?.strategic_account != null && typeof raw.strategic_account !== 'boolean') errors.push('strategic_account_invalid');
if (raw?.confidence != null && (!Number.isFinite(Number(raw.confidence)) || Number(raw.confidence) < 0 || Number(raw.confidence) > 1)) errors.push('confidence_invalid');
lead.enrichment = { ...(lead.enrichment ?? {}), status: errors.length ? 'failed' : 'validated', valid: errors.length === 0, errors, response: errors.length ? null : { industry: raw.industry ?? null, company_size: raw.company_size == null ? null : Number(raw.company_size), country: raw.country ?? null, strategic_account: raw.strategic_account ?? null, confidence: raw.confidence == null ? null : Number(raw.confidence) }, completed_at: new Date().toISOString() };
return [{ json: lead }];

const lead = JSON.parse(JSON.stringify($json));
const response = lead.enrichment?.response ?? {};
const missing = (value) => value === null || value === undefined || value === '';
lead.business = lead.business && typeof lead.business === 'object' ? lead.business : {};
for (const field of ['industry', 'company_size', 'country', 'strategic_account']) {
  if (missing(lead.business[field]) && !missing(response[field])) lead.business[field] = response[field];
}
lead.enrichment.status = 'completed';
lead.enrichment.merged_fields = lead.enrichment.requested_fields.filter((field) => !missing(response[field]));
lead.processing.updated_at = new Date().toISOString();
return [{ json: lead }];

