WITH input AS (SELECT $1::jsonb AS j), updated AS (
 UPDATE leads SET industry=COALESCE(leads.industry,input.j#>>'{business,industry}'),company_size=COALESCE(leads.company_size,NULLIF(input.j#>>'{business,company_size}','')::integer),country=COALESCE(leads.country,input.j#>>'{business,country}'),strategic_account=leads.strategic_account OR COALESCE((input.j#>>'{business,strategic_account}')::boolean,false),updated_at=now() FROM input WHERE leads.id=(input.j->>'lead_id')::uuid RETURNING leads.id
), event AS (
 INSERT INTO lead_events (lead_id,event_type,workflow_name,execution_id,payload,created_at) SELECT updated.id,'enrichment_completed','WF03_enrichment_qualification',$2,jsonb_build_object('status',input.j#>>'{enrichment,status}','merged_fields',COALESCE(input.j#>'{enrichment,merged_fields}','[]'::jsonb),'confidence',input.j#>'{enrichment,response,confidence}'),now() FROM updated,input
) SELECT input.j AS lead FROM input;

