const lead = JSON.parse(JSON.stringify($json.lead ?? $json));
// Centralized assessment/demo defaults. Replace these sets with approved business configuration.
const CONFIG = {
  highValueServices: new Set([
    'ai automation',
    'enterprise automation'
  ]), // TODO: configure approved high-value service names.
  mediumValueServices: new Set([
    'crm automation',
    'workflow automation'
  ]), // TODO: configure approved medium-value service names.
  targetMarkets: new Set([
    'egypt',
    'eg',
    'saudi arabia',
    'sa',
    'uae',
    'united arab emirates',
    'ae'
  ]), // TODO: configure approved target-market country names/codes.
  clearIntentKeywords: ['need', 'require', 'project', 'proposal', 'quote', 'implement', 'automation'],
  highUrgencyKeywords: ['urgent', 'immediately', 'asap'],
  mediumUrgencyKeywords: ['soon', 'this month', 'this quarter']
};
const norm = (v) => v == null ? '' : String(v).trim().toLowerCase();
const size = Number(lead.business?.company_size);
const companySize = Number.isFinite(size) ? (size >= 500 ? 25 : size >= 100 ? 20 : size >= 20 ? 10 : 5) : 0;
const service = norm(lead.business?.service_interest);
const declaredTier = norm(lead.business?.service_value_tier);
const tier = declaredTier || (CONFIG.highValueServices.has(service) ? 'high' : CONFIG.mediumValueServices.has(service) ? 'medium' : 'low');
const serviceValue = tier === 'high' ? 25 : tier === 'medium' ? 15 : 5;
const message = norm(lead.request?.message);
const declaredIntent = norm(lead.request?.intent);
const clearIntent = declaredIntent === 'clear_business_requirement' || CONFIG.clearIntentKeywords.some((word) => message.includes(word));
const intent = clearIntent ? 15 : 5;
const declaredUrgency = norm(lead.request?.urgency);
const derivedUrgency = declaredUrgency !== 'unknown' && declaredUrgency ? declaredUrgency : CONFIG.highUrgencyKeywords.some((word) => message.includes(word)) ? 'high' : CONFIG.mediumUrgencyKeywords.some((word) => message.includes(word)) ? 'medium' : 'low';
const urgency = derivedUrgency === 'high' ? 15 : derivedUrgency === 'medium' ? 10 : 0;
const geography = CONFIG.targetMarkets.has(norm(lead.business?.country)) || lead.business?.is_target_market === true ? 10 : 0;
const strategic = lead.business?.strategic_account === true ? 20 : 0;
const missingNonCritical = Array.isArray(lead.data_quality?.missing_fields) && lead.data_quality.missing_fields.length > 0;
const dataQualityPenalty = missingNonCritical ? -10 : 0;
const breakdown = { company_size: companySize, service_value: serviceValue, intent, urgency, geography, strategic_account: strategic, data_quality_penalty: dataQualityPenalty };
const calculated = Object.values(breakdown).reduce((sum, value) => sum + value, 0);
lead.qualification = { ...(lead.qualification ?? {}), rule_score: Math.min(100, Math.max(0, calculated)), score_breakdown: breakdown };
lead.scoring_context = { service_value_tier: tier, intent_basis: clearIntent ? 'clear_business_requirement' : 'general_inquiry', urgency_basis: derivedUrgency, configuration_notes: ['Demo business configuration treats AI Automation and Enterprise Automation as high-value services; CRM Automation and Workflow Automation as medium-value services.', 'Demo target markets are Egypt, Saudi Arabia, and UAE, including the configured country-code/name variants.', 'Intent and urgency keyword lists are centralized assessment/demo defaults and do not use Gemini.'] };
return [{ json: lead }];

const lead = JSON.parse(JSON.stringify($json));
const score = Number(lead.qualification?.rule_score ?? 0);
const strategic = lead.business?.strategic_account === true;
const classification = strategic || score >= 90 ? 'vip' : score >= 70 ? 'qualified' : score >= 40 ? 'nurture' : 'unqualified';
lead.qualification = { ...(lead.qualification ?? {}), rule_score: score, rule_classification: classification, score_breakdown: lead.qualification?.score_breakdown ?? {}, is_vip: classification === 'vip' };
lead.processing.updated_at = new Date().toISOString();
return [{ json: lead }];

