const lead = JSON.parse(JSON.stringify($json.lead ?? $json));
const assessmentInput = { business_need: lead.request?.message ?? null, service_interest: lead.business?.service_interest ?? null, industry: lead.business?.industry ?? null, company_size: lead.business?.company_size ?? null, country: lead.business?.country ?? null };
const prompt = `Independently assess the qualitative potential of this business lead. Do not calculate, infer, mention, or modify any deterministic numerical score or rule classification. Return only JSON with keys classification, urgency, intent, confidence, reason. classification must be one of high_potential, medium_potential, low_potential, unknown. urgency must be high, medium, or low. confidence must be between 0 and 1. reason must be a string or null. Input: ${JSON.stringify(assessmentInput)}`;
return [{ json: { lead, gemini_request: { prompt, expected_schema: { classification: 'high_potential|medium_potential|low_potential|unknown', urgency: 'high|medium|low', intent: 'string', confidence: '0..1', reason: 'string|null' } } } }];

const lead = JSON.parse(JSON.stringify($('Build Gemini Qualification Request').item.json.lead));
let raw = $json?.output ?? $json?.text ?? $json?.response ?? $json;
let parsed = raw;
const errors = [];
if ($json?.error) errors.push(`provider_error:${String($json.error.message ?? $json.error)}`);
if (typeof raw === 'string') {
  const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  if (!cleaned) errors.push('empty_response');
  else { try { parsed = JSON.parse(cleaned); } catch { errors.push('malformed_json'); } }
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) errors.push('response_not_object');
const classifications = ['high_potential', 'medium_potential', 'low_potential', 'unknown'];
const urgencies = ['high', 'medium', 'low'];
if (!classifications.includes(parsed?.classification)) errors.push('classification_invalid');
if (!urgencies.includes(parsed?.urgency)) errors.push('urgency_invalid');
if (!Number.isFinite(Number(parsed?.confidence)) || Number(parsed.confidence) < 0 || Number(parsed.confidence) > 1) errors.push('confidence_invalid');
if (parsed?.intent == null || typeof parsed.intent !== 'string') errors.push('intent_invalid');
if (!(parsed?.reason === null || typeof parsed?.reason === 'string')) errors.push('reason_invalid');
lead.ai_assessment = errors.length ? { valid: false, technical_failure: true, errors, raw_type: typeof raw } : { valid: true, technical_failure: false, classification: parsed.classification, urgency: parsed.urgency, intent: parsed.intent, confidence: Number(parsed.confidence), reason: parsed.reason };
return [{ json: lead }];

const lead = JSON.parse(JSON.stringify($json));
lead.qualification = { ...(lead.qualification ?? {}), ai_classification: 'unknown', ai_confidence: 0, ai_reason: null, final_status: 'manual_review', reason: `AI technical failure: ${(lead.ai_assessment?.errors ?? ['unavailable']).join(', ')}`, is_vip: lead.qualification?.rule_classification === 'vip' };
lead.processing = { ...(lead.processing ?? {}), status: 'manual_review', current_workflow: 'WF03_enrichment_qualification', next_workflow: 'WF04_routing_crm', last_error: lead.qualification.reason, updated_at: new Date().toISOString() };
lead.qualification_conflict = { conflict: true, type: 'ai_technical_failure' };
return [{ json: lead }];

const lead = JSON.parse(JSON.stringify($json));
const rule = lead.qualification?.rule_classification;
const ai = lead.ai_assessment?.classification;
const matrix = {
  vip: { high_potential: 'vip', medium_potential: 'vip', low_potential: 'manual_review', unknown: 'vip' },
  qualified: { high_potential: 'qualified', medium_potential: 'qualified', low_potential: 'manual_review', unknown: 'qualified' },
  nurture: { high_potential: 'manual_review', medium_potential: 'nurture', low_potential: 'nurture', unknown: 'nurture' },
  unqualified: { high_potential: 'manual_review', medium_potential: 'unqualified', low_potential: 'unqualified', unknown: 'unqualified' }
};
const finalStatus = matrix[rule]?.[ai];
if (!finalStatus) throw new Error(`Unsupported conflict matrix combination: ${rule}/${ai}`);
const conflict = finalStatus === 'manual_review';
const signal = conflict ? 'material_conflict' : ai === 'unknown' || ai === 'medium_potential' ? 'neutral_ai_signal' : 'deterministic_ai_agreement';
lead.qualification = { ...(lead.qualification ?? {}), ai_classification: ai, ai_confidence: lead.ai_assessment.confidence, ai_reason: lead.ai_assessment.reason, final_status: finalStatus, reason: conflict ? `Material deterministic/AI disagreement: rule=${rule}, ai=${ai}.` : `${signal}: deterministic classification ${rule} preserved.`, is_vip: rule === 'vip' };
lead.qualification_conflict = { conflict, type: signal };
lead.processing = { ...(lead.processing ?? {}), status: conflict ? 'manual_review' : 'processing', current_workflow: 'WF03_enrichment_qualification', next_workflow: 'WF04_routing_crm', last_error: null, updated_at: new Date().toISOString() };
return [{ json: lead }];

